-- tipo: SQL | Mount da Folha em 1 ida (COLABORADORES,CRS,EMPRESAS,CARGOS,CICLOS,BENEFICIOS,ENCARGOS,DISSIDIOS,TURNOVERS). Param: cicloId (0 = ciclo aberto default).
SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',c.ID,'NOME',c.NOME,'CR_ID',c.CR_ID,'EMPRESA_ID',c.EMPRESA_ID,'CARGO',c.CARGO,'DATA_ADMISSAO',c.DATA_ADMISSAO,'SALARIO',c.SALARIO,'TIPO_CONTRATO',c.TIPO_CONTRATO,'ATIVO',c.ATIVO,'CR_CODIGO',cr.CODIGO,'CR_NOME',cr.NOME,'EMPRESA_NOME',e.NOME)) FROM COLABORADOR c LEFT JOIN CENTRO_RESULTADO cr ON cr.ID = c.CR_ID LEFT JOIN EMPRESA e ON e.ID = c.EMPRESA_ID),JSON_ARRAY()) AS COLABORADORES,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'CODIGO',t.CODIGO,'NOME',t.NOME,'EMPRESA_ID',t.EMPRESA_ID,'ATIVO',t.ATIVO)) FROM CENTRO_RESULTADO t WHERE t.ATIVO = 'true'),JSON_ARRAY()) AS CRS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'NOME',t.NOME,'CNPJ',t.CNPJ,'ATIVO',t.ATIVO,'CRIADO_EM',t.CRIADO_EM)) FROM EMPRESA t WHERE 1=1),JSON_ARRAY()) AS EMPRESAS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'NOME',t.NOME,'SALARIO_MEDIO',t.SALARIO_MEDIO,'ATIVO',t.ATIVO)) FROM CARGO t WHERE t.ATIVO = 'true'),JSON_ARRAY()) AS CARGOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'NOME',t.NOME,'ANO',t.ANO,'STATUS',t.STATUS,'CRIADO_EM',t.CRIADO_EM,'VERSAO_ATUAL',t.VERSAO_ATUAL,'ULTIMO_MES_REALIZADO',t.ULTIMO_MES_REALIZADO,'VERSAO_CONTROLE',t.VERSAO_CONTROLE,'VERSAO_ORIGEM_ID',t.VERSAO_ORIGEM_ID,'CRIADO_POR',t.CRIADO_POR)) FROM CICLO t WHERE (t.STATUS != 'FECHADO' OR t.VERSAO_ATUAL = 'true')),JSON_ARRAY()) AS CICLOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'NOME',t.NOME,'TIPO',t.TIPO,'VALOR',t.VALOR,'PERCENTUAL',t.PERCENTUAL,'APLICA_PJ',t.APLICA_PJ,'APLICA_CLT',t.APLICA_CLT,'CICLO_ID',t.CICLO_ID)) FROM BENEFICIO t WHERE t.CICLO_ID = CASE WHEN {{cicloId}} > 0 THEN {{cicloId}} ELSE COALESCE((SELECT ID FROM CICLO WHERE VERSAO_ATUAL = 'true' ORDER BY ID DESC LIMIT 1), (SELECT ID FROM CICLO WHERE STATUS != 'FECHADO' ORDER BY ANO DESC, ID DESC LIMIT 1)) END),JSON_ARRAY()) AS BENEFICIOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'NOME',t.NOME,'PERCENTUAL',t.PERCENTUAL,'APLICA_PJ',t.APLICA_PJ,'APLICA_CLT',t.APLICA_CLT,'CICLO_ID',t.CICLO_ID)) FROM ENCARGO t WHERE t.CICLO_ID = CASE WHEN {{cicloId}} > 0 THEN {{cicloId}} ELSE COALESCE((SELECT ID FROM CICLO WHERE VERSAO_ATUAL = 'true' ORDER BY ID DESC LIMIT 1), (SELECT ID FROM CICLO WHERE STATUS != 'FECHADO' ORDER BY ANO DESC, ID DESC LIMIT 1)) END),JSON_ARRAY()) AS ENCARGOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',pd.ID,'CICLO_ID',pd.CICLO_ID,'EMPRESA_ID',pd.EMPRESA_ID,'PERCENTUAL',pd.PERCENTUAL,'MES_APLICACAO',pd.MES_APLICACAO,'CRIADO_EM',pd.CRIADO_EM,'EMPRESA_NOME',e.NOME)) FROM PREMISSA_DISSIDIO pd JOIN EMPRESA e ON e.ID = pd.EMPRESA_ID),JSON_ARRAY()) AS DISSIDIOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',pt.ID,'CICLO_ID',pt.CICLO_ID,'EMPRESA_ID',pt.EMPRESA_ID,'PERCENTUAL',pt.PERCENTUAL,'CRIADO_EM',pt.CRIADO_EM,'EMPRESA_NOME',e.NOME)) FROM PREMISSA_TURNOVER pt JOIN EMPRESA e ON e.ID = pt.EMPRESA_ID),JSON_ARRAY()) AS TURNOVERS